const answers = [];
if (asks('price', 'prices', 'cost', 'costs', 'how much', 'cena', 'ceni', 'kolku cini', 'цена', 'цени', 'колку чини', 'колку чинат', 'ценовник', 'cenovnik')) {
  answers.push((lang === 'mk' ? 'Нашите цени:\n' : 'Our prices:\n') + serviceLines());
}
if (business.address && asks('address', 'where', 'located', 'location', 'adresa', 'kade', 'адреса', 'каде', 'локација', 'lokacija')) {
  answers.push(lang === 'mk' ? `Се наоѓаме на ${business.address}.` : `We're at ${business.address}.`);
}
if (business.openingHours && asks('hours', 'open', 'opening', 'close', 'closing', 'working', 'rabotno', 'rabotite', 'otvoreno', 'работно', 'работите', 'отворено')) {
  answers.push((lang === 'mk' ? 'Работно време: ' : 'Opening hours: ') + hours());
}
const thanked = asks('thanks', 'thank you', 'thx', 'fala', 'blagodaram', 'фала', 'благодарам');

// --- Problems to mention first ----------------------------------------------------
function problemText(p) {
  const time = (p.message || '').match(/^(\d{2}:\d{2})/)?.[1];
  const max = (p.message || '').match(/up to (\d+)/)?.[1];
  const T = {
    TIME_NOT_AVAILABLE: { en: `Sorry, ${time || 'that time'} isn't free that day.`, mk: `За жал, ${time ? 'во ' + time : 'тој термин'} не е слободно тој ден.` },
    NO_AVAILABILITY_ON_DATE: { en: "Sorry, we're fully booked that day.", mk: 'За жал, тој ден немаме слободни термини.' },
    DATE_IN_PAST: { en: 'That date has already passed.', mk: 'Тој датум веќе помина.' },
    NO_TIMES_IN_PREFERENCE: { en: 'Nothing is free at that time of day.', mk: 'Во тој дел од денот нема слободни термини.' },
    SERVICE_NOT_FOUND: { en: "Sorry, we don't offer that service.", mk: 'За жал, таа услуга не ја нудиме.' },
    SERVICE_AMBIGUOUS: { en: 'A few of our services match that.', mk: 'Повеќе наши услуги одговараат на тоа.' },
    SERVICE_UNAVAILABLE: { en: "Sorry, that service can't be booked right now.", mk: 'За жал, таа услуга моментално не може да се закаже.' },
    INVALID_PARTICIPANTS: { en: `That service is for up to ${max || 'a few'} people.`, mk: `Таа услуга е за најмногу ${max || 'неколку'} лица.` },
    OPTION_NOT_RECOGNISED: { en: "That number isn't on the list.", mk: 'Тој број го нема во листата.' },
    RESOURCE_NOT_AVAILABLE: { en: "That choice isn't available at that time.", mk: 'Тој избор не е слободен во тоа време.' },
    INVALID_PHONE: { en: "That phone number doesn't look right. Could you check it?", mk: 'Телефонскиот број не изгледа точно. Може ли да го проверите?' },
    DISCOUNT_INVALID: { en: "That discount code can't be used, so I've left it off.", mk: 'Тој код за попуст не може да се искористи, па не го додадов.' },
    SLOT_JUST_TAKEN: { en: 'Sorry, someone just booked that time.', mk: 'За жал, некој штотуку го резервираше тој термин.' },
    INVALID_CUSTOMER_DETAILS: { en: "Something in your details didn't work. Could you send your phone number again?", mk: 'Нешто не е во ред со податоците. Може ли повторно да го испратите телефонскиот број?' },
    TEMPORARY_ERROR: { en: 'Sorry, something went wrong on our side.', mk: 'Извинете, нешто тргна наопаку кај нас.' },
    RESCHEDULE_NOT_SUPPORTED: { en: `I can't move a booking in chat yet. You can cancel it and book a new time, or call us${callUs}.`, mk: `Не можам да преместам резервација преку порака. Можете да го откажете и да закажете нов, или јавете ни се${callUs}.` },
  };
  return T[p.code]?.[lang] ?? null;
}

// --- The message for each step ----------------------------------------------------
const svc = summary.serviceName || reservation?.serviceName || '';
const when = day(summary.date);
const at = summary.start || '';
// The resource type is whatever the business configured: "Employee", "Table", "Court", "Room"...
// People get "who"; anything else is named by its type.
const missing = turn.missingFields || [];
const resourceType = turn.ask === 'RESOURCE' ? String(missing[0] || '') : '';
const isPerson = /employee|staff|therap|stylist|specialist|master|doctor|barber|trainer|coach|teacher|instructor|person|вработ|терапевт|фризер|доктор|тренер|инструктор/i.test(resourceType);
const name = summary.customerName ? summary.customerName.split(' ')[0] : (turn.customer?.firstName || '');

function bookingLines(r) {
  const lines = [r.serviceName, `${day(r.date)}, ${r.start}–${r.end}`];
  const chosen = (r.resources || []).map(x => x.name || x).filter(Boolean);
  if (chosen.length) lines.push((lang === 'mk' ? 'Избрано: ' : 'Selected: ') + chosen.join(', '));
  if (r.numberOfParticipants > 1) lines.push(lang === 'mk' ? `За ${r.numberOfParticipants} лица` : `For ${r.numberOfParticipants} people`);
  return lines;
}
function step() {
  const en = lang === 'en';
  if (outcome) {
    switch (outcome) {
      case 'RESERVATION_CREATED': {
        const r = reservation || {};
        // Only what the customer chose; rooms or chairs the business assigns stay internal.
        const lines = bookingLines({ serviceName: r.serviceName || svc, date: r.date || summary.date, start: r.start || at, end: r.end || summary.end, resources: summary.resources || [], numberOfParticipants: r.numberOfParticipants || summary.numberOfParticipants });
        return en
          ? `You're booked! ✅\n\n${lines.join('\n')}\nBooking number: ${r.id}\n\nSee you then! If you need to cancel, just message us here.`
          : `Резервирано! ✅\n\n${lines.join('\n')}\nБрој на резервација: ${r.id}\n\nВе очекуваме! Ако треба да откажете, само пишете ни тука.`;
      }
      case 'RESERVATION_CANCELLED':
        return en ? `Done, your ${reservation?.serviceName || 'booking'} on ${day(reservation?.date)} at ${reservation?.start} is cancelled. We hope to see you another time!`
          : `Готово, вашата резервација (${reservation?.serviceName || ''}, ${day(reservation?.date)} во ${reservation?.start}) е откажана. Се надеваме дека ќе се видиме друг пат!`;
      case 'BOOKING_ABANDONED':
        return en ? "No problem, I've stopped the booking. Message us any time you'd like to book." : 'Нема проблем, ја прекинав резервацијата. Пишете ни кога и да сакате да резервирате.';
      case 'CANCELLATION_ABORTED':
        return en ? 'Okay, your booking stays as it is.' : 'Во ред, вашата резервација останува како што е.';
      case 'NO_UPCOMING_RESERVATIONS':
        return en ? `I couldn't find any upcoming bookings made from this account. If you booked another way, please call us${callUs}.`
          : `Не најдов претстојни резервации направени од овој профил. Ако сте резервирале на друг начин, јавете ни се${callUs}.`;
      case 'CANCELLATION_NOT_ALLOWED':
        return en ? `This booking can't be cancelled here any more. Please call us${callUs} and we'll help you.`
          : `Оваа резервација веќе не може да се откаже тука. Ве молам јавете ни се${callUs} и ќе ви помогнеме.`;
      case 'CANCELLATION_FAILED':
        return en ? `Sorry, I couldn't cancel it just now. Please try again in a moment, or call us${callUs}.`
          : `Извинете, не успеав да ја откажам во моментов. Обидете се повторно за малку, или јавете ни се${callUs}.`;
    }
  }
  switch (turn.ask) {
    case 'SERVICE':
      return en ? `Which service would you like to book?\n\n${list(options)}\n\nJust reply with the number.` : `Која услуга сакате да ја закажете?\n\n${list(options)}\n\nОдговорете само со бројот.`;
    case 'PARTICIPANTS': {
      const max = summary.maxParticipants > 1 ? summary.maxParticipants : null;
      return en ? `How many people is the ${svc} for?${max ? ` (up to ${max})` : ''}` : `За колку лица е ${svc}?${max ? ` (најмногу ${max})` : ''}`;
    }
    case 'DATE':
      if (options.length) return en ? `These are the next days with free times:\n\n${list(options)}\n\nReply with the number, or tell me another day.` : `Ова се следните денови со слободни термини:\n\n${list(options)}\n\nОдговорете со бројот или напишете друг ден.`;
      return en ? `What day would you like to book ${svc} for?` : `За кој ден би сакале да резервирате ${svc}?`;
    case 'TIME':
      return en ? `Here are the free times for ${svc} on ${when}:\n\n${list(options)}\n\nReply with the number or the time that suits you.` : `Слободни термини за ${svc}, ${when}:\n\n${list(options)}\n\nОдговорете со бројот или со часот што ви одговара.`;
    case 'RESOURCE': {
      const type = resourceType.toLowerCase();
      if (isPerson) return en ? `Who would you like for your ${svc} on ${when} at ${at}?\n\n${list(options)}\n\nReply with the number or the name, or say "no preference".` : `Кај кого би сакале да резервирате (${svc}, ${when} во ${at})?\n\n${list(options)}\n\nОдговорете со бројот или името, или напишете „сеедно“.`;
      return en ? `Which ${type || 'option'} would you like for ${svc} on ${when} at ${at}?\n\n${list(options)}\n\nReply with the number or the name, or say "no preference".` : `Изберете${type ? ' ' + type : ''} (${svc}, ${when} во ${at}):\n\n${list(options)}\n\nОдговорете со бројот или името, или напишете „сеедно“.`;
    }
    case 'CUSTOMER_INFO':
      if (missing.includes('firstName') && missing.includes('phone')) return en ? `Almost done! To book ${svc} on ${when} at ${at}, I just need your first name and phone number.` : `Уште малку! За да ја направам резервацијата (${svc}, ${when} во ${at}), ми требаат вашето име и телефонски број.`;
      if (missing.includes('phone')) return en ? `Thanks${name ? ', ' + name : ''}! And what's your phone number?` : `Ви благодарам${name ? ', ' + name : ''}! Кој е вашиот телефонски број?`;
      return en ? 'Thanks! And what name should I put the booking under?' : 'Ви благодарам! На кое име да ја запишам резервацијата?';
    case 'CONFIRMATION': {
      const lines = bookingLines({ serviceName: svc, date: summary.date, start: at, end: summary.end, resources: summary.resources, numberOfParticipants: summary.numberOfParticipants });
      if (summary.customerName) lines.push((en ? 'Name: ' : 'Име: ') + summary.customerName);
      const p = summary.price;
      if (p) {
        const discounted = p.discountAmount && Number(p.discountAmount) > 0;
        lines.push((en ? 'Price: ' : 'Цена: ') + money(p.finalPrice, p.currency) + (discounted ? (en ? ` (instead of ${money(p.originalPrice, p.currency)})` : ` (наместо ${money(p.originalPrice, p.currency)})`) : ''));
      }
      return en ? `Here's your booking:\n\n${lines.join('\n')}\n\nShall I confirm it? Reply yes or no.` : `Еве ја вашата резервација:\n\n${lines.join('\n')}\n\nДа ја потврдам? Одговорете со да или не.`;
    }
    case 'CANCEL_SELECTION': {
      const rs = turn.reservations || [];
      const opts = options.map(o => { const r = rs.find(x => String(x.id) === String(o.value)); return r ? { ...o, label: `${r.serviceName}, ${day(r.date)} ${en ? 'at' : 'во'} ${r.start}` } : o; });
      return en ? `Which booking would you like to cancel?\n\n${list(opts)}\n\nReply with the number.` : `Која резервација сакате да ја откажете?\n\n${list(opts)}\n\nОдговорете со бројот.`;
    }
    case 'CANCEL_CONFIRMATION': {
      const r = reservation || {};
      return en ? `You have ${r.serviceName} on ${day(r.date)} at ${r.start}. Do you want me to cancel it? Reply yes or no.` : `Имате резервација за ${r.serviceName}, ${day(r.date)} во ${r.start}. Дали сакате да ја откажам? Одговорете со да или не.`;
    }
  }
  // Nothing in progress: answer, thank, or introduce what the bot does.
  if (answers.length) return en ? 'Would you like to make a booking?' : 'Дали сакате да направите резервација?';
  if (thanked) return en ? "You're welcome! 😊" : 'Нема на што! 😊';
  return en ? `Welcome to ${business.name || 'us'}! I can make a booking for you right here.\n\nWe offer:\n${serviceLines()}\n\nJust tell me what you'd like and when.`
    : `Добредојдовте во ${business.name || 'нас'}! Можам да направам резервација за вас веднаш тука.\n\nНудиме:\n${serviceLines()}\n\nСамо напишете што сакате и кога.`;
}

// Greeting and short notes go in front of the step, on one line; longer blocks get their own paragraph.
const prefix = [];
if (!context.conversationId && !outcome && !(turn.ask === 'NOTHING' && (answers.length || thanked))) prefix.push(lang === 'mk' ? 'Здраво!' : 'Hi!');
const sameQuestion = context.conversationId && turn.ask === context.asked && !outcome;
if (sameQuestion && !Object.keys(extracted).length && !problems.length && !answers.length) {
  prefix.push(lang === 'mk' ? 'Извинете, не ве разбрав добро.' : "Sorry, I didn't quite catch that.");
}
for (const p of problems) { const t = problemText(p); if (t) prefix.push(t); }
const blocks = [prefix.join(' '), ...answers, step()].filter(Boolean);
const templateReply = blocks.some(b => b.includes('\n')) || blocks.length > 2 ? blocks.join('\n\n') : blocks.join(' ');

// Optional: let a language model rephrase the same facts (REPLY_WRITER=llm).
const LANGUAGE_NAME = { en: 'English', mk: 'Macedonian' };
const modelFacts = { ...facts, customerLanguage: LANGUAGE_NAME[lang], conversationStarted: !!context.conversationId };
const system = "You write the next chat message from a business to its customer on Instagram or Facebook Messenger. You are the business's friendly booking assistant: warm, brief, natural — never robotic, never stiff.\n\nYou are given FACTS from the booking system and a DRAFT reply that is already correct. Rephrase the draft naturally in customerLanguage without changing any fact, number, time, name or option. Keep the numbered options exactly as in the draft. Do not greet again when conversationStarted is true. Never say a booking is made unless the draft says so. Plain text only, no markdown, at most one emoji, under 700 characters. Return only the message text.";
const content = `CUSTOMER WROTE: ${message.slice(0, 2000)}\n\nFACTS:\n${JSON.stringify(modelFacts, null, 1)}\n\nDRAFT:\n${templateReply}`;
const claudeModel = $env.CLAUDE_MODEL || 'claude-opus-5-5';
const tuned = !claudeModel.startsWith('claude-haiku');
return [{ json: {
  useModel,
  templateReply,
  anthropicRequest: { model: claudeModel, max_tokens: 4000, ...(tuned ? { fallbacks: 'default', output_config: { effort: 'low' } } : {}), system, messages: [{ role: 'user', content }] },
  ollamaRequest: { model: $env.OLLAMA_MODEL || 'qwen2.5:7b-instruct', stream: false, keep_alive: '30m', options: { temperature: 0.3, num_ctx: 8192 }, messages: [{ role: 'system', content: system }, { role: 'user', content }] },
} }];

const prepared = $('Prepare reply').first().json;
let reply = null;
if (prepared.useModel) {
  const response = $input.first().json;
  if (response.statusCode === 200 && response.body?.stop_reason !== 'refusal') {
    reply = (response.body.message?.content ?? (response.body.content || []).filter(b => b.type === 'text').map(b => b.text).join('')).trim();
  }
}
// The template is always correct; it is also the fallback when the model fails.
reply = reply || prepared.templateReply || "Sorry, I'm having trouble checking availability right now. Please try again in a few minutes.";
return [{ json: { reply: reply.slice(0, 1900), fallback: prepared.fallback === true } }];
